    if (!popup) {
      setError('Please allow pop-ups for this site, then try Google sign-in again.');
      return;
    }
    dismissGooglePopup();
    googlePopupRef.current = popup;
    popup.focus();
    setError('');
    setIsLoading(true);
    const version = ++requestVersion.current;
    const roleAtOpen = userRole;
    const deadline = Date.now() + 5 * 60 * 1000;
